      "34歳女性。検診で乳がんの疑いを指摘された。血縁者の多くが乳がんを発症していたため、乳がんの遺伝子検査及び組織診断を受けた。その結果、HER2陽性乳がんと診断された。骨転移があるため、ドセタキセル/カルボプラチン/トラスツズマブの併用療法のレジメンに従い、薬物治療が始まった。",
    field: "衛生",

    question:
      "34歳女性。検診で乳がんの疑いを指摘された。血縁者の多くが乳がんを発症していたため、乳がんの遺伝子検査及び組織診断を受けた。その結果、HER2陽性乳がんと診断された。骨転移があるため、ドセタキセル/カルボプラチン/トラスツズマブの併用療法のレジメンに従い、薬物治療が始まった。\n\n遺伝性乳がんの発症に関わる遺伝子はどれか。1つ選べ。",

