    caseContext:
      "71歳男性。50年前から喫煙習慣がある（喫煙指数：1200）。階段歩行時に息切れを訴え近医を受診し、慢性閉塞性肺疾患（COPD）と診断され、以下の処方が出された。\n\n（処方1）\nチオトロピウム臭化物水和物吸入用カプセル 18 μg\n1回1カプセル　1日1回吸入　全56カプセル\n\n（処方2）\nテオフィリン徐放錠 200 mg（12〜24時間持続）　1回1錠（1日2錠）\n1日2回　朝食後・就寝前　56日分\n\n（処方3）\nフドステイン錠 200 mg　1回2錠（1日6錠）\n1日3回　朝昼夕食後　56日分",
