      "64歳男性。BMI 28.5。糖尿病で近医に通院中であった。全身倦怠感を訴え、浮腫も認められたため精査目的で入院となった。入院時の持参薬と検査データは以下の通りである。\n\n（持参薬）\nグリメピリド錠1 mg　1回2錠（1日1回）　朝食後\nロサルタンK錠50 mg　1回1錠（1日1回）　朝食後\nメトホルミン塩酸塩錠250 mg　1回2錠（1日3回）　朝昼夕食後\nプラバスタチンNa錠10 mg　1回1錠（1日1回）　夕食後\n\n（検査データ）\nBUN 49.8 mg/dL、血清クレアチニン4.38 mg/dL、血圧152/93 mmHg、Hb 8.5 g/dL、Alb 2.7 g/dL、Na 140 mEq/L、K 4.9 mEq/L、空腹時血糖224 mg/dL、HbA1c 7.1%、低密度リポタンパク質コレステロール（LDL-C）99 mg/dL、高密度リポタンパク質コレステロール（HDL-C）48 mg/dL、トリグリセリド（TG）120 mg/dL、尿タンパク（3＋）",
    field: "法規",

    question:
      "病棟の担当薬剤師は、入院直後にこの患者と面談し、持参薬と服薬状況を確認した。薬の飲み残しが多かったため、薬剤師が治療についての考えを聴いたところ、次のような発言があった。\n「ちゃんとやらなければならないことは分かっていますし、自分なりにやろうと努めていますが、なかなか実践できません。」\nこの発言から、男性は、行動変容ステージモデルのどの段階にあると考えられるか。適切なのを1つ選べ。",

    choices: [
    "無関心期",
    "関心期",
    "準備期",
    "実行期",
    "維持期"
    ],

    answer: 2,


    explanation:
      "正答は3の準備期です。行動変容ステージモデルでは、準備期は「必要性を理解し、近いうちに行動しようとしているが、まだ十分に実行できていない段階」と考えます。本症例では、「やらなければならないことは分かっている」「自分なりにやろうと努めているが、実践できない」と発言しており、行動への意思はあるものの継続的な実行には至っていないため、準備期が適切です。無関心期は行動変容の必要性を感じていない段階、関心期は必要性を感じ始めているが具体的行動には乏しい段階です。実行期は実際に行動を開始して継続している段階、維持期はその行動が長期間継続できている段階を指すため、本症例とは異なります。"
