    explanation:
      "サリドマイドは催奇形性が極めて問題となるため、製造販売業者による厳格な安全管理体制（TERMS）が整備されています。また、承認時には全症例を対象とした製造販売後調査が求められました。女性にも投与自体は可能ですが、妊娠回避などの管理が必須です。多発性骨髄腫に対しては、国家試験上は再発又は難治性の場合に用いられる薬として押さえます。一方、希少疾病用医薬品の再審査期間は通常10年とされ、20年ではありません。したがって、適切でないのは2です。"
