    question:
      "5歳女児。欠神発作（てんかん小発作）と診断され、保険薬局へ処方箋を持参した。処方量 [[A|]] mg と秤取量 [[B|]] g の組合せで最も適切なのはどれか。1つ選べ。なお、エトスクシミドの原薬量は成人量として1日450 mgである。小児への投与量は下記の式で計算せよ。\n\n小児量＝（年齢×4＋20）/100 × 成人量\n\n（処方）\nエトスクシミド散50% 1回 [[A|]] mg （1日（A×2）mg）【原薬量】\n1日2回 朝夕食後 7日分\n\n実秤取量（7日分） エトスクシミド散50% [[B|]] g",

